function geneRows(){let genome=S.inspectedGenome||S.genome;return genome.genes.map((g,i)=>`<div class="gene-row" data-gene="${i}"><span class="gene-id">${g.id} ${g.mutation?'⚠':''}</span><span class="gene-function">${g.name}<small>${g.regulation.toUpperCase()} · chr ${g.chromosome}</small></span><div class="expression-bar"><i style="width:${Math.round(traitMap(genome,S.env)[g.name]*100)}%"></i></div><span class="gene-value">${f(traitMap(genome,S.env)[g.name],2)}×</span></div>`).join('')}
