function elementResultMarkup(){let element=ELEMENTS.find(e=>e.symbol===S.selectedElement)||ELEMENTS.find(e=>e.symbol==='C'),guide=ELEMENT_GUIDE[element.symbol],detail=guide||{title:`${element.name} · periodic-table reference`,badge:'GENERAL ELEMENT CONTEXT',description:`${element.name} (symbol ${element.symbol}, atomic number ${element.number}) is shown here as an educational periodic-table reference. GENESIS does not model this element’s chemistry, biological availability, reactions, or effects on the selected cell.`,source:ELEMENT_REFERENCE.source,url:ELEMENT_REFERENCE.url},cell=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],count=cell?.elementExposures?.[element.symbol]||0,total=Object.values(cell?.elementExposures||{}).reduce((sum,n)=>sum+n,0);return `<div class="element-result"><div class="element-result-symbol"><small>ATOMIC NO. ${element.number}</small><strong>${element.symbol}</strong><span>${element.name}</span></div><div class="element-result-copy"><div class="element-result-top"><h3>${detail.title}</h3><span class="tag cyan">${detail.badge}</span></div><p>${detail.description}</p><a href="${detail.url}" target="_blank" rel="noopener noreferrer">Source: ${detail.source} ↗</a><div class="element-plate-response"><div><strong>Selected cell · ${cell?.id||'none'}</strong><span>${count} ${element.symbol} marker${count===1?'':'s'} · ${total} total sandbox marker${total===1?'':'s'}</span></div><button class="subtle-button" data-action="add-element-plate" ${cell?'':'disabled'}>＋ Add ${element.symbol} to plate</button></div><p class="element-response-note">Adds a persistent, visual-only exposure marker to this cell. The marker triggers a brief halo; it does not represent a dose, chemical reaction, or biological effect, and does not alter cell metrics.</p></div></div>`}
function cellView(){if(!S.plate?.length)Object.assign(S,makePlateState(S.genome,S.seed,S.viability,S.atp,0));let selected=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],genome=plateGenome(selected),traits=traitMap(genome,S.env),atpExpression=traits['ATP synthase']||.5,stage=cycleStage(selected.cycleProgress||0),checkpoint=cycleCheckpoint(selected),organelles=[['Cell membrane',`${f(selected.membrane,1)}% integrity · transport boundary`],['Cytoplasm',`${f(atpExpression*100,0)}% metabolic activity`],['Nucleus',`${genome.genes.length} annotated loci · ${genome.id}`],['Mitochondria',`${f(selected.atp,2)} mmol/L ATP proxy · ROS ${f(selected.ros,1)}`],['Ribosomes',`${genome.genes.length} active transcript targets`],['Endoplasmic reticulum',`${f((traits['Heat-shock protein']||.5)*100,0)}% folding response · load ${f(selected.proteinLoad,1)}%`],['Golgi apparatus','Protein processing'],['Lysosomes','Turnover · autophagy proxy'],['Cytoskeleton',`${selected.archived?'archived':'live'} lineage · generation ${selected.generation}`],['Cell receptors',`${f((S.env.nutrients+.2)*7,1)} relative signal capacity`]];return `${pageHead(`LIVE IMAGING · CELL ${String(S.tick%9999).padStart(4,'0')}`,'Cell observatory','Every pulse reflects the selected cell’s genome and measured state.',`<button class="subtle-button" data-action="plate-live">＋ Add live cells</button><button class="subtle-button" data-action="cell-cycle">↻ Advance cell cycle</button><button class="subtle-button" data-action="stain">◉ Stain selected</button>`)}<section class="card plate-card"><div class="card-head"><div><span class="card-title">Observatory plate <span class="card-meta">/ CULTURE DISH · ${S.plate.length} OF 30 CELLS</span></span><div class="plate-caption">Select any cell to inspect it. Pulse rate and hue are derived from its expressed genome.</div></div><span class="tag green">${S.plate.length} ON PLATE</span></div><div class="plate-stage"><div class="plate-dish"><div class="plate-rim"></div><div class="plate-well"></div>${S.plate.map(plateCellMarkup).join('')}<span class="plate-crosshair h"></span><span class="plate-crosshair v"></span></div><div class="plate-overlay"><span>FIELD 01</span><span>${S.playing?'MOTION ACTIVE':'MOTION CONTINUES'}</span></div></div><div class="plate-summary"><span>MEAN VIABILITY <b>${f(S.plate.reduce((n,c)=>n+c.viability,0)/S.plate.length,1)}%</b></span><span>STAINED <b>${S.plate.filter(c=>c.stained).length}</b></span><span>MEAN DAMAGE <b>${f(S.plate.reduce((n,c)=>n+(c.damage||0),0)/S.plate.length,1)}%</b></span><span>MEAN ROS <b>${f(S.plate.reduce((n,c)=>n+(c.ros||0),0)/S.plate.length,1)}%</b></span><span>CHECKPOINT BLOCKED <b>${S.plate.filter(c=>cycleCheckpoint(c)!=='PASS').length}</b></span><span>CAPACITY <b>${30-S.plate.length} OPEN</b></span></div><div class="plate-footer"><div class="plate-legend"><span><i class="plate-legend-dot"></i>LIVE CULTURE</span><span><i class="plate-legend-dot archive"></i>ARCHIVED LINEAGE</span><span><i class="plate-legend-dot selected"></i>SELECTED</span></div><div class="plate-load"><select id="plate-archive" aria-label="Choose archived cell"><option value="">Load archived cell…</option>${(S.archive||[]).map((g,i)=>`<option value="${i}">${g.id} · generation ${g.generation}</option>`).join('')}</select><button class="tiny-control" data-action="plate-archive">LOAD TO PLATE</button></div></div></section><div class="cell-layout plate-details"><section class="card"><div class="card-head"><span class="card-title">Selected cell · ${selected.id}</span><span class="tag ${selected.archived?'':'green'}">${selected.sourceLabel}</span></div><div class="selected-lineage"><strong>${genome.id}</strong><span>${genome.species||'Pelagomyces isolate'} · generation ${selected.generation}</span></div><div class="cell-reading"><span>VIABILITY</span><b>${f(selected.viability,1)} %</b></div><div class="cell-reading"><span>ATP · MODEL PROXY</span><b>${f(selected.atp,2)} mmol/L</b></div><div class="cell-reading"><span>DAMAGE · MODEL PROXY</span><b>${f(selected.damage||0,1)} %</b></div><div class="cell-reading"><span>OXIDATIVE STRESS · ROS</span><b>${f(selected.ros||0,1)} %</b></div><div class="cell-reading"><span>PROTEIN-FOLDING LOAD</span><b>${f(selected.proteinLoad||0,1)} %</b></div><div class="cell-reading"><span>MEMBRANE INTEGRITY</span><b>${f(selected.membrane??100,1)} %</b></div><div class="cell-reading"><span>CELL STATE</span><b class="state-${selected.state}">${selected.state.toUpperCase()}</b></div><div class="cell-reading"><span>CYCLE STAGE</span><b>${stage} · ${f((selected.cycleProgress||0)*100,0)} %</b></div><div class="cell-reading"><span>DIVISION CHECKPOINT</span><b class="checkpoint-${checkpoint==='PASS'?'pass':'blocked'}">${checkpoint}</b></div><div class="cell-reading"><span>AGE · SIMULATION TICKS</span><b>${(selected.age||0).toLocaleString()}</b></div><div class="cell-reading"><span>DIVISIONS</span><b>${selected.divisions||0}</b></div><div class="cell-reading"><span>DOMINANT EXPRESSION</span><b>${Object.entries(traits).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—'}</b></div><div class="cell-reading"><span>GENOME GC CONTENT</span><b>${f(gc(genome.sequence),1)} %</b></div><button class="action-button primary inspect-action" data-action="inspect-genome">⌁ &nbsp; Inspect this genome</button><button class="subtle-button inspect-action" data-action="remove-cell">× Remove selected cell from plate</button></section><section class="card"><div class="card-head"><span class="card-title">Organelle registry</span><span class="card-meta">SELECTED CELL · RELATIVE</span></div><div class="organelle-list">${organelles.map(o=>`<div class="organelle-row"><span>${o[0]}</span><small>${o[1]}</small></div>`).join('')}</div><div class="disclaimer">Cell motion is a schematic model. ATP, viability and gene-expression values are educational proxies, not biological predictions.</div></section></div><section class="card periodic-card"><div class="card-head"><div><span class="card-title">Periodic table <span class="card-meta">/ EDUCATIONAL REFERENCE</span></span><div class="plate-caption">Select an element for curated context, then optionally add a visual-only marker to the selected cell.</div></div><span class="tag cyan">118 ELEMENTS</span></div>${periodicTableMarkup()}${elementResultMarkup()}<div class="disclaimer">Educational context only: this reference does not model chemical reactions, concentrations, or biological effects. Plate markers are visual annotations only; they do not change cell metrics or predict real-cell responses.</div></section>`}
const PROTOCOLS=[['DNA extraction','⌁','Lyse sampled cells and isolate nucleic acid.','SAMPLE REQUIRED · 15 MIN'],['RNA extraction','∿','Recover RNA; degradation can reduce yield.','SAMPLE REQUIRED · 12 MIN'],['PCR amplification','⤴','Amplify a selected locus from extracted DNA.','DNA EXTRACT · 2 H'],['Gel electrophoresis','▥','Separate fragments by approximate length.','PCR PRODUCT · 45 MIN'],['Sanger sequencing','↠','Read a short amplicon with terminal-variation limits.','PCR PRODUCT · 3 H'],['Whole-genome sequencing','⌘','Estimate full simulated reference and variant calls.','DNA EXTRACT · 8 H'],['Gene expression assay','≋','Measure expression from model transcript abundance.','RNA EXTRACT · 1 H'],['Protein analysis','◈','Infer translated peptide profile and relative abundance.','CELL LYSATE · 2 H'],['Cell viability','◉','Estimate viable fraction using a virtual dye-exclusion count.','LIVE CULTURE · 10 MIN'],['Karyotype','▤','Inspect chromosome count and large-scale abnormalities.','CELL CULTURE · 4 H'],['CRISPR edit simulation','✳','Model a targeted sequence edit; outcomes are simplified.','DESIGN + DNA · 1 DAY'],['Comparative genomics','⇄','Compare this genome with archived lineages.','2 ASSEMBLIES · 20 MIN']];
function resultMarkup(){let r=S.labResults[0];if(!r)return '<div class="result-empty">Select a protocol to configure and run a traceable experiment.<br><br><span class="tag">RESULTS WILL REFERENCE THE ACTIVE GENOME</span></div>';return `<div class="result-title"><div><strong>${r.protocol}</strong><div class="card-meta" style="margin-top:5px">${r.id} · ${r.date} · ${r.genome}</div></div><span class="tag green">COMPLETE</span></div><div class="result-data">${r.values.map(v=>`<div class="result-cell"><span>${v[0]}</span><strong>${v[1]}</strong></div>`).join('')}</div><p style="font-size:10px;color:#8e9b91;line-height:1.55;margin:13px 0 0">${r.note}</p>`}
function labView(){let req=activeProtocol==='DNA extraction'?'Ready for extraction':S.samples.dna?'DNA extract available':'Sample available · extract DNA first';return `${pageHead(`EXPERIMENTAL SUITE · PROTOCOL ${String(S.experimentCount+1).padStart(3,'0')}`,'Wet lab','Run simplified, traceable procedures against your organism’s actual genome.',`<span class="tag ${S.samples.dna?'green':''}">${req.toUpperCase()}</span>`)}<div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Protocol library</span><span class="card-meta">12 METHODS · MODELLED</span></div><div class="protocol-grid">${PROTOCOLS.map(p=>`<button class="protocol-option ${activeProtocol===p[0]?'selected':''}" data-protocol="${p[0]}"><div class="protocol-icon">${p[1]}</div><strong>${p[0]}</strong><p>${p[2]}</p><small>${p[3]}</small></button>`).join('')}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Bench configuration</span><span class="card-meta">${activeProtocol.toUpperCase()}</span></div><div class="gene-detail"><div class="mini-stat"><span>SUBJECT / REFERENCE</span><strong>${S.genome.id}<small> · generation ${S.generation}</small></strong></div><label class="modal-label" style="display:block;font:9px var(--mono);color:#829188;margin:17px 0 6px">TARGET LOCUS</label><select class="select-button" id="target-gene" style="width:100%">${S.genome.genes.map(g=>`<option value="${g.id}">${g.id} · ${g.name}</option>`).join('')}<option value="whole">Whole genome</option></select><div class="chip-row"><span class="chip">SAMPLE ${S.samples.dna?'DNA EXTRACTED':'LIVE CULTURE'}</span><span class="chip">REPLICATE n=1</span></div><button class="action-button primary" style="width:100%;margin-top:6px" data-action="run-lab">▶ &nbsp; Run ${activeProtocol}</button></div></section><section class="card"><div class="card-head"><span class="card-title">Latest result</span><span class="card-meta">${S.labResults.length} EXPERIMENTS</span></div><div class="lab-result">${resultMarkup()}</div></section><div class="disclaimer">Educational simulation only. Protocol outputs are deterministic estimates from this model, not clinical or laboratory instructions. No wet-lab procedure is being performed.</div></div></div>`}
function notebookView(){let items=S.notebook.map(n=>`<div class="notebook-entry"><span class="note-date">${n.date} · ${n.id} · ${n.protocol||'FIELD NOTE'}</span><h3>${n.title}</h3><p>${n.text}</p></div>`).join('');return `${pageHead(`RESEARCH LOG · ${S.notebook.length} ENTRIES`,'Research notes','A reproducible notebook of observations and experimental outcomes.',`<button class="action-button primary" data-action="add-note">＋ Add field note</button>`)}<section class="card"><div class="card-head"><span class="card-title">Laboratory notebook</span><span class="card-meta">PERSISTED LOCALLY · ${S.events.length} FIELD OBSERVATIONS</span></div>${items||'<div class="empty-state">No notes recorded. Run an experiment or add a field note to begin.</div>'}</section><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Recent field observations</span><span class="card-meta">AUTO-RECORDED</span></div><div class="event-list">${eventRows()}</div></section>`}
function archiveView(){let arr=S.archive||[];return `${pageHead('REFERENCE LIBRARY · LOCAL DATABASE','Genome archive','Preserve discovered lineages and use them to seed future worlds.',`<button class="subtle-button" data-action="export">↓ Export database</button><button class="action-button primary" data-action="save-genome">＋ Save current</button>`)}<section class="card"><div class="card-head"><span class="card-title">Archived genomes</span><span class="card-meta">${arr.length} REFERENCES · BROWSER LOCAL STORAGE</span></div>${arr.length?arr.map((g,i)=>`<div class="archive-item"><div class="archive-glyph">⌁</div><div class="archive-info"><strong>${g.id} ${g.species||'· ancestral isolate'}</strong><small>${g.genes.length} genes · ${g.sequence.length.toLocaleString()} bp · generation ${g.generation} · GC ${f(gc(g.sequence),1)}% · saved ${g.saved}</small></div><div class="archive-actions"><button class="tiny-control" data-action="use-genome" data-index="${i}">SEED WORLD</button><button class="tiny-control" data-action="download-genome" data-index="${i}">↓</button></div></div>`).join(''):'<div class="empty-state">Your reference library is empty.<br><br>Archive a sequenced genome to make it available as a starting point for future research.</div>'}</section><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Database record</span><span class="card-meta">JSON · OFFLINE-FIRST</span></div><div class="gene-detail"><p>Genomes are stored in this browser’s local storage and persist across sessions on this device. Export the database to keep a portable backup. Imported files are read as genome seed records.</p><button class="subtle-button" data-action="import">↑ Import genome JSON</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></section>`}
function codexView(){if(!codexUnlocked())return `${pageHead('REFERENCE LIBRARY · ACCESS LOCKED','DNA Codex','A curated field guide to DNA, genomes, and the methods used to study them.')}<section class="card codex-lock"><div class="codex-lock-icon">⌬</div><div class="eyebrow">CODEX SEALED</div><h2>${S.plate.length?'Complete a research success to unlock the Codex':'Place a biological source on the observatory plate'}</h2><p>The Codex becomes available when a source is present on the plate and at least one lab protocol or genome-sequencing run succeeds. Curated reference material remains hidden until then.</p><div class="codex-unlock-steps"><span class="${S.plate.length?'complete':''}">01 · SOURCE ON PLATE</span><span class="${S.researchSuccesses?'complete':''}">02 · RESEARCH SUCCESS</span></div><button class="action-button primary" data-view="cell">Open cell observatory →</button></section>`;return `${pageHead(`REFERENCE LIBRARY · ${DNA_CODEX.length} FIELD NOTES`,'DNA Codex','A curated educational guide to what is known about DNA—and how evidence is interpreted.',`<span class="tag green">UNLOCKED · ${S.researchSuccesses} SUCCESS${S.researchSuccesses===1?'':'ES'}</span>`)}<section class="card codex-intro"><div><div class="eyebrow">SCOPE &amp; CONTEXT</div><h2>DNA is a molecule, not a complete explanation.</h2><p>This living reference summarizes established concepts across molecular biology, genomics, evolution, and research practice. It is intentionally curated—not an exhaustive database of every sequence, organism, or discovery. Scientific knowledge changes, and model readouts elsewhere in GENESIS are educational proxies rather than real biological measurements.</p></div><div class="codex-stat"><strong>${DNA_CODEX.length}</strong><span>TOPIC GUIDES</span><small>${S.plate.length} source cells present</small><span class="codex-level">RESEARCHER LEVEL ${S.researchLevel}</span><small>${S.researchXP} / ${S.researchLevel*100} XP to next level</small></div></section><div class="codex-grid">${DNA_CODEX.map((entry,i)=>`<article class="card codex-entry"><div class="codex-entry-top"><span class="codex-index">${String(i+1).padStart(2,'0')}</span><span class="tag">${entry.category}</span></div><h2>${entry.title}</h2><p>${entry.text}</p></article>`).join('')}</div><section class="card codex-citation"><strong>Reading critically</strong><p>These notes provide a starting point, not medical or laboratory advice. For current details, consult peer-reviewed reviews, curated databases, and organism-specific sources; distinguish observed evidence from hypotheses and simulations.</p></section>`}
function settingsModal(){return `<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>Simulation settings</h2><button class="modal-close" data-action="close-modal">×</button></div><p>Adjust the scale and persistence of this educational model. Changes are saved on this device.</p><div class="settings-row"><span>Simulation speed</span><select id="setting-speed"><option value="1" ${S.speed===1?'selected':''}>1× · observed</option><option value="4" ${S.speed===4?'selected':''}>4× · accelerated</option><option value="10" ${S.speed===10?'selected':''}>10× · rapid</option></select></div><div class="settings-row"><span>Autoplay on load</span><b>${S.playing?'ON':'OFF'}</b></div><div class="settings-row"><span>Storage</span><b>LOCAL · ${Math.round(JSON.stringify(S).length/1024)} KB</b></div><div class="modal-footer"><button class="subtle-button" data-action="close-modal">Close</button><button class="action-button danger" data-action="reset-world">Reset current world</button></div></div></div>`}
function render(){const root=$('#view-root');const pages={overview,genome:genomeView,cell:cellView,evolution:evolutionView,lab:labView,notebook:notebookView,archive:archiveView,codex:codexView};root.innerHTML=(pages[currentView]||overview)();$('#breadcrumb-current').textContent=({overview:'LIVING SYSTEM',genome:'GENOME EXPLORER',cell:'CELL OBSERVATORY',evolution:'EVOLUTION',lab:'WET LAB',notebook:'RESEARCH NOTES',archive:'GENOME ARCHIVE',codex:'DNA CODEX'})[currentView];$('#seed-label').textContent=String(S.seed).slice(-8).toUpperCase();$('#run-label').textContent=S.playing?'LIVE SIMULATION':'SIMULATION PAUSED';$('#simulation-status').textContent=S.playing?'SIMULATION RUNNING':'SIMULATION PAUSED';$('#gene-count-nav').textContent=String(S.genome.genes.length).padStart(2,'0');$('#archive-count').textContent=(S.archive||[]).length;let unlocked=codexUnlocked(),codexNav=$('#codex-nav'),levelNeed=S.researchLevel*100;$('#codex-nav-status').textContent=unlocked?'OPEN':'LOCKED';codexNav?.setAttribute('aria-label',`DNA Codex ${unlocked?'unlocked':'locked'}`);$('#player-level').textContent=String(S.researchLevel);$('#player-xp').textContent=`${S.researchXP} / ${levelNeed} XP`;$('#player-xp-bar').style.width=`${Math.min(100,S.researchXP/levelNeed*100)}%`;$('#player-progress').title=`${S.researchXP} XP toward level ${S.researchLevel+1}; ${S.researchSuccesses} successful research actions`;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));if(currentView==='overview'){drawEcosystem();drawTrend()}}
function newWorld(source){let progress={researchXP:S.researchXP,researchLevel:S.researchLevel,researchSuccesses:S.researchSuccesses};S=initialState(`GEN-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,source);S.archive=loadState()?.archive||[];Object.assign(S,progress);S.notebook=[];S.playing=false;storeState();currentView='overview';render();toast(source?`New world seeded from ${source.id}`:'A new biological history has begun. Researcher progress retained.')}
function saveGenome(){if(!S.samples.dna){toast('Sequence the genome before archiving it.');return}S.archive=S.archive||[];if(S.archive.some(g=>g.id===S.genome.id)){toast('This genome is already archived.');return}S.archive.unshift({...JSON.parse(JSON.stringify(S.genome)),species:'Pelagomyces isolate',sequence:S.genome.sequence,saved:new Date().toLocaleDateString()});storeState();render();toast('Genome archived for future worlds.')}
function addNotebook(title,text,protocol='FIELD NOTE'){S.notebook=S.notebook||[];S.notebook.unshift({id:`N-${String(S.notebook.length+1).padStart(3,'0')}`,date:new Date().toLocaleString(),title,text,protocol});storeState()}
function sample(){S.samples.dna=true;S.samples.rna=true;S.events.unshift({tick:S.tick,type:'lab',text:`Biomass sample collected from ${S.genome.id}; ${S.liveCells.toLocaleString()||S.cellCount.toLocaleString()} cells available for assay.`});addNotebook('Biomass sample collected',`Sample from ${S.genome.id} at generation ${S.generation}. Estimated biomass: ${S.cellCount.toLocaleString()} cells; viability ${f(S.viability,1)}%.`, 'SAMPLE');storeState();toast('Sample collected. DNA and RNA extracts are now available.');if(currentView==='lab'||currentView==='notebook')render()}
function runLab(){let p=activeProtocol,gene=S.genome.genes.find(g=>g.id===$('#target-gene')?.value)||S.genome.genes[0],rng=new RNG(hashSeed(`${S.seed}:${p}:${S.experimentCount}:${gene.id}`)),seq=S.genome.sequence,err=.001+rng.next()*.012;let values=[],note='',needsDNA=['PCR amplification','Gel electrophoresis','Sanger sequencing','Whole-genome sequencing','CRISPR edit simulation'].includes(p),needsRNA=['Gene expression assay'].includes(p);if((needsDNA&&!S.samples.dna)||(needsRNA&&!S.samples.rna)){toast(needsDNA?'Collect a biological sample and extract DNA first.':'Collect a biological sample and extract RNA first.');return}
switch(p){case'DNA extraction':S.samples.dna=true;values=[['DNA yield',`${(S.cellCount*.00012*(.7+rng.next()*.6)).toFixed(2)} µg`],['A260 / A280',`${(1.72+rng.next()*.18).toFixed(2)}`],['Estimated purity',`${(87+rng.next()*11).toFixed(1)}%`]];note=`Extracted from the ${S.cellCount.toLocaleString()}-cell simulated specimen. The sequence reference contains ${seq.length.toLocaleString()} bp; purity and yield include modeled extraction variability.`;break;
case'RNA extraction':S.samples.rna=true;values=[['RNA yield',`${(S.cellCount*.00008*(.7+rng.next()*.5)).toFixed(2)} µg`],['Integrity proxy',`${(6+rng.next()*3).toFixed(1)} / 10`],['Active transcripts',`${S.genome.genes.length} loci`]];note='Yield reflects specimen scale. Integrity is a simplified degradation proxy; gene-level expression values are computed from this world’s regulatory state.';break;
case'PCR amplification':values=[['Target',gene.id],['Amplicon',`${gene.coding.length} bp`],['GC content',`${f(gc(gene.coding),1)}%`]];note=`The simulated primer target is derived from ${gene.name} coding sequence. Amplification is idealized; off-target binding and polymerase kinetics are not modeled.`;break;
case'Gel electrophoresis':values=[['Band estimate',`${gene.coding.length} bp`],['Resolution',`${(30+rng.next()*20).toFixed(0)} bp`],['Band intensity',`${(70+rng.next()*30).toFixed(0)}%`]];note=`Fragment size is based on the actual ${gene.id} coding region. Resolution is approximate and would not reliably distinguish fragments closer than the reported limit.`;break;
case'Sanger sequencing':S.samples.dna=true;values=[['Read length',`${Math.min(800,gene.coding.length)} bp`],['Called bases',`${gene.coding.length} bp`],['Expected error',`${(err*100).toFixed(2)}%`]];note=`Sequence called against ${gene.id} (${gene.name}); reference GC ${f(gc(gene.coding),1)}%. A short-read educational estimate, not a chromatogram or real sequencing result.`;break;
case'Whole-genome sequencing':S.samples.dna=true;values=[['Read coverage',`${(18+rng.next()*22).toFixed(1)}×`],['Assembly length',`${seq.length.toLocaleString()} bp`],['Variant calls',`${S.genome.mutations} inherited`]];note=`Reference assembly computed directly from this genome. Coverage and error are simulated; no raw reads or real instrument model are generated.`;break;
case'Gene expression assay':values=[['Target',gene.name],['Relative expression',`${f(traitMap(S.genome,S.env)[gene.name],3)}×`],['Replicate CV',`${(err*100*2).toFixed(1)}%`]];note=`Expression is calculated from ${gene.regulation} promoter response, current environmental conditions and epigenetic state. Variation is an assay-noise estimate.`;break;
case'Protein analysis':values=[['Predicted peptide',translate(transcribe(gene))],['Length',`${translate(transcribe(gene)).length} aa`],['Relative abundance',`${f(traitMap(S.genome,S.env)[gene.name],2)}×`]];note=`In-silico translation of ${gene.id}; protein abundance follows modeled transcription. Folding, post-translational modifications, and proteomics spectra are not simulated.`;break;
case'Cell viability':values=[['Estimated viable',`${f(S.viability,1)}%`],['Cells counted',`${S.cellCount.toLocaleString()}`],['95% CI',`±${f(1.96*Math.sqrt(S.viability*(100-S.viability)/Math.max(1,S.cellCount)),1)} pp`]];note='Binomial confidence interval assumes independent, representative sampled cells. Model state is correlated, so interval is likely optimistic.';break;
case'Karyotype':values=[['Chromosome count',`${S.genome.chromosomes} pairs (model)`],['Aneuploidy detected','None modeled'],['Confidence','Low · schematic']];note='Chromosome count is generated at world creation. Structural rearrangements and cell-to-cell karyotype variation are not represented.';break;
case'CRISPR edit simulation':values=[['Target locus',gene.id],['Edit outcome','In-silico substitution'],['Predicted phenotype',gene.name]];note=`A single coding-base change is modeled in ${gene.id}. Off-target edits, repair pathways, mosaicism, delivery, and biological safety are outside this educational simulation.`;gene.coding=gene.coding.slice(0,3)+({A:'G',T:'C',C:'A',G:'T'}[gene.coding[3]])+gene.coding.slice(4);gene.mutation={from:'simulated',position:3};gene.activity=clamp(gene.activity*.96,.05,1);S.genome.mutations++;S.genome.sequence=genomeSequence(S.genome);S.damage=clamp(S.damage+.4,0,100);break;
case'Comparative genomics':{let ref=(S.archive||[]).find(x=>x.id!==S.genome.id);let sim=ref?sequenceSimilarity(seq,ref.sequence):1;values=[['Reference',ref?.id||'No archived reference'],['Sequence identity',`${f(sim*100,2)}%`],['Length difference',`${ref?seq.length-ref.sequence.length:0} bp`]];note=ref?'Identity is an aligned-position similarity proxy (not a full alignment); reference selected from the first archived genome.':'Archive a second genome to enable between-lineage comparisons.';break}}
S.experimentCount++;let result={id:`EXP-${String(S.experimentCount).padStart(3,'0')}`,date:new Date().toLocaleString(),protocol:p,genome:S.genome.id,values,note};S.labResults.unshift(result);S.events.unshift({tick:S.tick,type:'lab',text:`${p} completed on ${S.genome.id}; ${values[0][1]} recorded.`});addNotebook(`${p} · ${result.id}`,note,p);let progress=recordResearchSuccess(p);storeState();render();toast(`${researchSuccessToast(p,progress)} · ${result.id}`)}
function sequenceSimilarity(a,b){if(!b)return 1;let n=Math.min(a.length,b.length),same=0;for(let i=0;i<n;i++)if(a[i]===b[i])same++;return same/Math.max(a.length,b.length)}
function doSequence(){if(!S.samples.dna){toast('Collect a sample and extract DNA before sequencing.');currentView='lab';activeProtocol='DNA extraction';render();return}S.genome.sequence=genomeSequence(S.genome);S.samples.sequenced=true;let bases=S.genome.sequence.length;S.events.unshift({tick:S.tick,type:'lab',text:`Sequence assembly completed for ${S.genome.id}; ${bases.toLocaleString()} bp in the simulated reference.`});addNotebook('Genome sequencing completed',`Assembled ${bases.toLocaleString()} bp with GC content ${f(gc(S.genome.sequence),2)}%. ${S.genome.genes.length} model genes annotated.`, 'SEQUENCING');let progress=recordResearchSuccess('Genome sequencing');storeState();render();toast(`${bases.toLocaleString()} bp assembled · ${researchSuccessToast('Genome sequencing',progress)}`)}
function download(name,data,type='application/json'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function handleAction(action){let a=typeof action==='string'?action:action.dataset.action;switch(a){case'toggle':S.playing=!S.playing;storeState();render();toast(S.playing?'Simulation resumed.':'Simulation paused.');break;case'add-element-plate':{let cell=S.plate.find(c=>c.id===S.selectedCellId),symbol=S.selectedElement;if(!cell){toast('Select a cell on the plate first.');return}cell.elementExposures=cell.elementExposures||{};cell.elementExposures[symbol]=(cell.elementExposures[symbol]||0)+1;let cellId=cell.id;storeState();render();let marker=$(`[data-plate-cell="${cellId}"]`);marker?.classList.add('element-pulse');setTimeout(()=>marker?.classList.remove('element-pulse'),1800);toast(`${symbol} sandbox marker added to ${cell.id}.`);break}case'sample':sample();break;case'sequence':doSequence();break;case'save-genome':saveGenome();break;case'run-lab':runLab();break;case'evolve':S.playing=false;for(let i=0;i<10;i++){S.tick+=25;generationStep()}storeState();render();toast('Ten generations simulated with inherited variation.');break;case'plate-live':{let added=addCellsToPlate(S.genome,false,6);render();if(added.length)toast(`${added.length} live cells added to the observatory plate.`);break}case'plate-archive':{let value=$('#plate-archive')?.value,index=Number(value),genome=value!==''?S.archive?.[index]:null;if(!Number.isInteger(index)||!genome){toast('Choose an archived genome first.');return}let added=addCellsToPlate(genome,true,6);render();if(added.length)toast(`${added.length} cells from ${genome.id} added to the plate.`);break}case'inspect-genome':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell)return;S.inspectedGenome=JSON.parse(JSON.stringify(plateGenome(cell)));S.selectedGene=0;currentView='genome';render();break}case'clear-inspection':delete S.inspectedGenome;S.selectedGene=0;render();break;case'cell-cycle':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell){toast('Select a cell first.');break}cell.atp=clamp(cell.atp-.12,.2,7);cell.cycleProgress=1;let checkpoint=cycleCheckpoint(cell),divided=checkpoint==='PASS'&&dividePlateCell(cell);let outcome=divided?'passed checkpoint and divided':checkpoint!=='PASS'?`held at checkpoint: ${checkpoint}`:'passed checkpoint; division capped by plate capacity';S.events.unshift({tick:S.tick,type:'lab',text:`${cell.id} ${outcome}.`});addNotebook('Cell cycle checkpoint',`${cell.id} ${outcome}. ATP proxy ${f(cell.atp,2)} mmol/L; division count ${cell.divisions||0}.`,'CELL CYCLE');storeState();render();toast(divided?'Checkpoint passed; daughter cell added to the plate.':checkpoint!=='PASS'?`Division paused by checkpoint: ${checkpoint}.`:'Checkpoint passed; plate is full, so division is capped.');break}case'stain':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell){toast('Select a cell first.');break}cell.stained=true;cell.stainIntensity=clamp(cell.viability*.7+cell.membrane*.3,0,100);S.events.unshift({tick:S.tick,type:'lab',text:`Fluorescent viability stain applied to ${cell.id}.`});addNotebook('Fluorescent stain applied',`${cell.id} stained; fluorescence intensity proxy ${f(cell.stainIntensity,1)}% combines viability and membrane integrity.`,'STAINING');storeState();render();toast('Selected cell stained; fluorescence reflects viability and membrane integrity.');break}case'remove-cell':{if(S.plate.length<=1){toast('Keep at least one cell on the observatory plate.');break}let index=S.plate.findIndex(c=>c.id===S.selectedCellId);if(index<0)break;let [removed]=S.plate.splice(index,1);S.selectedCellId=S.plate[Math.min(index,S.plate.length-1)].id;storeState();render();toast(`${removed.id} removed from the plate.`);break}case'add-note':$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>Add field note</h2><button class="modal-close" data-action="close-modal">×</button></div><label>Observation title</label><input id="note-title" placeholder="e.g. Increased stress response" maxlength="90"><label>Notes / hypothesis</label><textarea id="note-body" placeholder="Record an observation, hypothesis, or next step…"></textarea><div class="modal-footer"><button class="subtle-button" data-action="close-modal">Cancel</button><button class="action-button primary" data-action="save-note">Save to notebook</button></div></div></div>`;break;case'save-note':{let title=$('#note-title')?.value.trim(),text=$('#note-body')?.value.trim();if(!title||!text){toast('Add a title and observation first.');return}addNotebook(title,text);$('#modal-root').innerHTML='';currentView='notebook';render();toast('Field note saved.');break}case'export':download('genesis-database.json',JSON.stringify({format:'genesis-genome-archive-v1',archive:S.archive||[],notebook:S.notebook||[]},null,2));break;case'import':$('#import-file').click();break;case'download-genome':{let g=S.archive[Number(action.dataset.index)];if(g)download(`${g.id}.json`,JSON.stringify(g,null,2));break}case'use-genome':{let g=S.archive[Number(action.dataset.index)];if(g)newWorld(g);break}case'close-modal':$('#modal-root').innerHTML='';break;case'reset-world':$('#modal-root').innerHTML='';newWorld();break}}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();return}let plateCell=e.target.closest('[data-plate-cell]');if(plateCell){S.selectedCellId=plateCell.dataset.plateCell;storeState();render();return}let element=e.target.closest('[data-element]');if(element){S.selectedElement=element.dataset.element;storeState();render();return}let action=e.target.closest('[data-action]');if(action){handleAction(action);return}let p=e.target.closest('[data-protocol]');if(p){activeProtocol=p.dataset.protocol;render();return}let sp=e.target.closest('[data-speed]');if(sp){S.speed=Number(sp.dataset.speed);storeState();render();return}let gene=e.target.closest('[data-gene]');if(gene){S.selectedGene=Number(gene.dataset.gene);render();return}if(e.target.closest('#new-world')){newWorld();return}if(e.target.closest('#settings-btn')){$('#modal-root').innerHTML=settingsModal();return}if(e.target.closest('#seed-button')){navigator.clipboard?.writeText(String(S.seed));toast('World seed copied.');return}if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''});
document.addEventListener('input',e=>{if(e.target.matches('[data-env]')){let key=e.target.dataset.env;S.env[key]=Number(e.target.value);let label=e.target.closest('.env-control')?.querySelector('label b');if(label){let unit=label.textContent.replace(/^[-+\d.,\s]+/,'');label.textContent=`${f(S.env[key],1)} ${unit}`.trim()}} });
document.addEventListener('change',e=>{if(e.target.matches('[data-env]')){storeState();render()}if(e.target.id==='setting-speed'){S.speed=Number(e.target.value);storeState()}if(e.target.id==='import-file'&&e.target.files?.[0]){let reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result),g=data.genome||data;if(!g.genes||!g.sequence)throw Error('Missing genome sequence or gene annotations');S.archive=S.archive||[];S.archive.unshift({...g,saved:new Date().toLocaleDateString()});storeState();render();toast(`Imported genome ${g.id}`)}catch(err){toast(`Import failed: ${err.message}`)}};reader.readAsText(e.target.files[0])}});
window.addEventListener('resize',()=>{if(currentView==='overview'){drawEcosystem();drawTrend()}});render();
function evolutionView(){let rows=S.history.slice(-12).reverse().map(x=>`<div class="timeline-row"><span class="timeline-gen">GEN ${String(x.generation).padStart(3,'0')}</span><div class="timeline-bar"><i style="width:${Math.max(4,x.fitness*100)}%"></i></div><span class="timeline-fit">${f(x.fitness*100,1)}% · ${x.population}</span></div>`).join('');let traits=expressionProfile(S.genome,S.env).slice(0,5);return `${pageHead(`POPULATION DYNAMICS · ${S.generation} GENERATIONS`,'Evolution','Inheritance, selection and drift unfold under changing conditions.',`<button class="subtle-button" data-action="evolve">⤴ Advance 10 generations</button><button class="action-button primary" data-action="toggle">${S.playing?'Ⅱ Pause':'▶ Resume'}</button>`)}<div class="metric-strip">${metric('GENERATION',String(S.generation).padStart(3,'0'),'reproductive cycles')}${metric('POPULATION',S.population.toLocaleString(),'individuals · effective proxy')}${metric('RELATIVE FITNESS',`${f(S.fitness*100,1)}%`,'environment-relative index')}${metric('MUTATION RATE',`${f(.1+S.env.radiation*.8,2)}%`,'per locus · model assumption')}</div><div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Lineage fitness</span><span class="card-meta">SELECTION HISTORY · LAST 12</span></div><div class="timeline">${rows||'<div class="empty-state">No generation events yet. Resume or advance the simulation.</div>'}</div></section><section class="card"><div class="card-head"><span class="card-title">Population composition</span><span class="card-meta">PHENOTYPE PROXIES</span></div><div class="population-bars">${traits.map((g,i)=>`<div class="pop-row"><span>${g.name.split(' ')[0]}</span><div class="pop-track"><i style="width:${g.expression*100}%"></i></div><span>${f(g.expression*100,0)}%</span></div>`).join('')}<p style="font-size:9px;color:#75857b;margin:18px 0 0">Trait frequencies approximate expression prevalence; this is not an individual-based population-genetics model.</p></div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Environmental conditions</span><span class="card-meta">CHANGES AFFECT REGULATORY EXPRESSION & FITNESS</span></div><div class="env-grid">${[['temperature','Temperature','°C',0,40],['radiation','Radiation','relative',0,1],['nutrients','Nutrient availability','fraction',0,1],['oxygen','Oxygen availability','fraction',0,1],['water','Water availability','fraction',0,1],['ph','pH','',4,10],['chemical','Chemical stress','relative',0,1]].map(([key,label,unit,min,max])=>`<div class="env-control"><label><span>${label}</span><b>${f(S.env[key],1)} ${unit}</b></label><input type="range" min="${min}" max="${max}" step=".1" value="${S.env[key]}" data-env="${key}" /></div>`).join('')}</div></section>`}
function genomeView(){let genome=S.inspectedGenome||S.genome,g=genome.genes[S.selectedGene]||genome.genes[0],slice=g.promoter+g.enhancer+g.coding.slice(0,18)+g.intron.slice(0,16)+g.coding.slice(18),sequence=slice.split('').map((x,i)=>`<span class="${i<g.promoter.length?'promoter':i>=g.promoter.length+g.enhancer.length&&i<g.promoter.length+g.enhancer.length+g.coding.length?'highlight':''}">${x}</span>`).join('');return `${pageHead(`MOLECULAR RECORD · ${genome.id}`,'Genome explorer','A living sequence, transcribed and translated into phenotype.',S.inspectedGenome?'<button class="subtle-button" data-view="cell">← Observatory</button><button class="action-button primary" data-action="clear-inspection">× Clear inspection</button>':`<button class="subtle-button" data-action="sequence">${S.samples.dna?'↻ Resequence':'⌁ Sequence genome'}</button><button class="action-button primary" data-action="save-genome">＋ Archive genome</button>`)}<div class="metric-strip">${metric('ASSEMBLED LENGTH',`${genome.sequence.length.toLocaleString()}<small> bp</small>`,'estimated · simulated reference')}${metric('GC CONTENT',`${f(gc(genome.sequence),1)}<small>%</small>`,'sequence composition')}${metric('PREDICTED GENES',genome.genes.length,'annotated ORFs')}${metric('CHROMOSOMES',genome.chromosomes,'haploid model')}</div><div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Gene annotation <span class="card-meta">/ ${genome.genes.length} loci</span></span><span class="tag green">LIVE EXPRESSION</span></div><div class="gene-list">${geneRows()}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Locus sequence · ${g.id}</span><span class="tag">CHROMOSOME ${g.chromosome}</span></div><div class="gene-detail"><div class="sequence-display"><div>${sequence}</div><div class="sequence-caption"><span>5′ → 3′ · CODING STRAND</span><span>${slice.length} BP</span></div></div><div class="chip-row"><span class="chip">PROMOTER ${g.promoter}</span><span class="chip">ENHANCER ${g.enhancer}</span><span class="chip">${g.intron.length} BP INTRON</span></div><p><strong style="color:#dce4dd">${g.name}</strong> — ${g.role}. ${g.regulation} regulation. Predicted peptide: <span style="color:var(--lime);font-family:var(--mono)">${translate(transcribe(g))}</span></p><div class="mini-stat"><span>EXPRESSION LEVEL · RELATIVE MODEL UNITS</span><strong class="stat-good">${f(traitMap(genome,S.env)[g.name],3)}<small>× baseline</small></strong></div></div></section><section class="card"><div class="card-head"><span class="card-title">Sequence context</span><span class="card-meta">NON-CODING DNA</span></div><div class="gene-detail"><div class="sequence-display">${S.genome.noncoding.slice(0,84).split('').map((x,i)=>`<span style="color:${['#9bafa3','#9bd8c3','#d0b77e','#a6c078'][i%4]}">${x}</span>`).join('')}<div class="sequence-caption"><span>INTERGENIC REGION</span><span>84 BP SHOWN</span></div></div><p>Non-coding sequence contributes regulatory context in this model; sequence shown is generated, not a reference biological genome.</p></div></section></div></div>`}
